\begin{example}[Cut locus of a sphere]
  \label{ex:dc-ch13-2-3}
  \dcref{ch13:2.3}
  If $M^n=S^n$ and $p\in S^n$, the cut locus of $p$ is its antipodal point. Here the
  cut locus of $p$ coincides with the locus of conjugate points to $p$.
\end{example}

